#!/bin/sh
# Generated by `python -m lensgate ddl --roles`. Do not edit by hand.
# One warehouse login per Metabase connection, each able to read only its own schemas.
set -eu
psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" <<SQL
REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE CONNECT ON DATABASE "$POSTGRES_DB" FROM PUBLIC;
CREATE ROLE wh_sales LOGIN PASSWORD '${LENSGATE_PG_WH_SALES_PASSWORD:?set LENSGATE_PG_WH_SALES_PASSWORD}';
GRANT CONNECT ON DATABASE "$POSTGRES_DB" TO wh_sales;
GRANT USAGE ON SCHEMA ref TO wh_sales;
GRANT SELECT ON ALL TABLES IN SCHEMA ref TO wh_sales;
GRANT USAGE ON SCHEMA sales TO wh_sales;
GRANT SELECT ON ALL TABLES IN SCHEMA sales TO wh_sales;
CREATE ROLE wh_ops LOGIN PASSWORD '${LENSGATE_PG_WH_OPS_PASSWORD:?set LENSGATE_PG_WH_OPS_PASSWORD}';
GRANT CONNECT ON DATABASE "$POSTGRES_DB" TO wh_ops;
GRANT USAGE ON SCHEMA ref TO wh_ops;
GRANT SELECT ON ALL TABLES IN SCHEMA ref TO wh_ops;
GRANT USAGE ON SCHEMA ops TO wh_ops;
GRANT SELECT ON ALL TABLES IN SCHEMA ops TO wh_ops;
CREATE ROLE wh_people LOGIN PASSWORD '${LENSGATE_PG_WH_PEOPLE_PASSWORD:?set LENSGATE_PG_WH_PEOPLE_PASSWORD}';
GRANT CONNECT ON DATABASE "$POSTGRES_DB" TO wh_people;
GRANT USAGE ON SCHEMA ref TO wh_people;
GRANT SELECT ON ALL TABLES IN SCHEMA ref TO wh_people;
GRANT USAGE ON SCHEMA people TO wh_people;
GRANT SELECT ON ALL TABLES IN SCHEMA people TO wh_people;
CREATE ROLE wh_finance LOGIN PASSWORD '${LENSGATE_PG_WH_FINANCE_PASSWORD:?set LENSGATE_PG_WH_FINANCE_PASSWORD}';
GRANT CONNECT ON DATABASE "$POSTGRES_DB" TO wh_finance;
GRANT USAGE ON SCHEMA ref TO wh_finance;
GRANT SELECT ON ALL TABLES IN SCHEMA ref TO wh_finance;
GRANT USAGE ON SCHEMA finance TO wh_finance;
GRANT SELECT ON ALL TABLES IN SCHEMA finance TO wh_finance;
CREATE ROLE wh_exec LOGIN PASSWORD '${LENSGATE_PG_WH_EXEC_PASSWORD:?set LENSGATE_PG_WH_EXEC_PASSWORD}';
GRANT CONNECT ON DATABASE "$POSTGRES_DB" TO wh_exec;
GRANT USAGE ON SCHEMA ref TO wh_exec;
GRANT SELECT ON ALL TABLES IN SCHEMA ref TO wh_exec;
GRANT USAGE ON SCHEMA sales TO wh_exec;
GRANT SELECT ON ALL TABLES IN SCHEMA sales TO wh_exec;
GRANT USAGE ON SCHEMA ops TO wh_exec;
GRANT SELECT ON ALL TABLES IN SCHEMA ops TO wh_exec;
GRANT USAGE ON SCHEMA people TO wh_exec;
GRANT SELECT ON ALL TABLES IN SCHEMA people TO wh_exec;
GRANT USAGE ON SCHEMA finance TO wh_exec;
GRANT SELECT ON ALL TABLES IN SCHEMA finance TO wh_exec;
SQL
